(window.LADDER_CARDS=window.LADDER_CARDS||{})["43a"]=[{"q": "What does m ≡ b (mod n) mean?", "a": "n divides m − b", "w": ["m divides b", "m and b are both below n", "m − b is below n"], "why": "The definition laid down in 43a1."}, {"q": "What is −1 on the clock of 12?", "a": "[11]", "w": ["[1]", "[12]", "it has no hour"], "why": "−1 − 11 = −12, a multiple of 12."}, {"q": "How many hours has ℤ/n?", "a": "n", "w": ["n − 1", "n + 1", "endlessly many"], "why": "The clock-hours technique: [0], …, [n − 1]."}, {"q": "Which technique makes [m] + [b] = [m + b] well defined?", "a": "carry-to-the-clock", "w": ["difference-test", "clock-cancel", "clock-hours"], "why": "Same hours in give the same hour out, for plus and times."}, {"q": "Which technique of the integers does not come along to a clock?", "a": "order", "w": ["spread for times over plus", "turn-about for times", "0 changes nothing in a sum"], "why": "On the clock of 12, [11] + [1] = [0]."}, {"q": "When can [a] be cancelled on the clock of n?", "a": "exactly when gcd(a, n) = 1", "w": ["whenever [a] ≠ [0]", "exactly when a is prime", "never"], "why": "The clock-cancel technique."}, {"q": "What is 38 · 47 on the clock of 9, by casting out nines?", "a": "[4]", "w": ["[0]", "[2]", "[8]"], "why": "38 ≡ 2 and 47 ≡ 2, and 2 · 2 = 4; 1786 has digit sum 22 ≡ 4."}, {"q": "Does 1 ≡ 6 (mod 5) give 2¹ ≡ 2⁶ (mod 5)?", "a": "no", "w": ["yes", "only for odd bases", "yes, by carry-to-the-clock"], "why": "The exponent is a count, not an hour: 2 against 64 ≡ 4."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43b"]=[{"q": "When does [a] have an undo on the clock of n?", "a": "exactly when gcd(a, n) = 1", "w": ["exactly when a < n", "whenever [a] ≠ [0]", "exactly when n is odd"], "why": "The undo-exactly-when technique."}, {"q": "What is [17]⁻¹ on the clock of 43?", "a": "[38]", "w": ["[5]", "[1/17]", "[26]"], "why": "17 · 38 = 646 = 15 · 43 + 1."}, {"q": "Which technique writes gcd(a, n) as ax + ny?", "a": "gcd-as-a-sum", "w": ["undo-exactly-when", "units-group", "clock-cancel"], "why": "4j13 with the multiple taken across."}, {"q": "What are the units of the clock of 12?", "a": "[1], [5], [7], [11]", "w": ["every hour but [0]", "[1] and [11]", "[2], [3], [4], [6]"], "why": "The hours sharing nothing with 12."}, {"q": "When is the clock of n a field?", "a": "exactly when n is prime", "w": ["exactly when n is odd", "always", "never"], "why": "The prime-clock-field technique."}, {"q": "Solve 17x ≡ 5 (mod 43).", "a": "x ≡ 18", "w": ["x ≡ 38", "x ≡ 5", "no answer"], "why": "x ≡ 38 · 5 = 190 ≡ 18."}, {"q": "Why does [6] have no undo on the clock of 9?", "a": "[6][3] = [0]", "w": ["6 is even", "9 is not prime, so no hour has an undo", "6 > 9/2"], "why": "gcd(6, 9) = 3: [6] multiplies a nonzero hour to [0]."}, {"q": "Which fact of rung 19 shows a product of units is a unit?", "a": "socks and shoes: [b]⁻¹[a]⁻¹ undoes [a][b]", "w": ["order divides the size", "every group turns about", "the part-group test"], "why": "19c."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43c"]=[{"q": "What does the remainder technique need of m and n?", "a": "that they share no divisor above 1", "w": ["that both are prime", "that m < n", "nothing"], "why": "gcd(m, n) = 1 makes the reading one-to-one."}, {"q": "The soldiers leave 2, 3, 2 in threes, fives and sevens. How many, below 105?", "a": "23", "w": ["7", "233", "105"], "why": "2 · 70 + 3 · 21 + 2 · 15 = 233 ≡ 23."}, {"q": "Which number is 1 on the clock of 3 and 0 on the clocks of 5 and 7?", "a": "70", "w": ["35", "21", "15"], "why": "35 · 2, with 2 the undo of 35 ≡ 2 on the clock of 3."}, {"q": "How many answers has x² ≡ 1 on the clock of 15?", "a": "four", "w": ["two", "one", "fifteen"], "why": "±1 on each of the clocks of 3 and 5: 1, 4, 11, 14."}, {"q": "How many units has the clock of 12, by the two-clock technique?", "a": "4", "w": ["11", "6", "2"], "why": "2 from the clock of 3 times 2 from the clock of 4."}, {"q": "Do x ≡ 1 (mod 4) and x ≡ 2 (mod 6) have an answer?", "a": "no", "w": ["yes, one hour of the clock of 24", "yes, x = 5", "yes, one hour of the clock of 12"], "why": "gcd = 2 and 1 ≢ 2 (mod 2): the shared-divisor technique."}, {"q": "Does the clock of 4 match the pairs from the clocks of 2 and 2, keeping plus?", "a": "no", "w": ["yes", "only for times", "only for odd hours"], "why": "[1] needs four additions to reach [0]; every pair needs two."}, {"q": "x ≡ 1 (mod 4) and x ≡ 1 (mod 6): the answers are one hour of which clock?", "a": "12", "w": ["24", "2", "10"], "why": "The least common multiple: 1 and 13 both answer."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43d"]=[{"q": "p is prime and p ∤ a. What is a^(p − 1) on the clock of p?", "a": "1", "w": ["a", "0", "p − 1"], "why": "The little technique."}, {"q": "How many units has the clock of 360?", "a": "96", "w": ["120", "72", "359"], "why": "360 · ½ · ⅔ · ⅘ = 96."}, {"q": "What is the last digit of 7²²²?", "a": "9", "w": ["7", "1", "3"], "why": "c(10) = 4, 222 ≡ 2, 7² = 49."}, {"q": "On which clock does the exponent of a unit live, for the clock of n?", "a": "the clock of the count of units of n", "w": ["the clock of n", "the clock of n − 1", "no clock"], "why": "The exponent-clock technique."}, {"q": "How long is the repeating block of 1/41?", "a": "5", "w": ["40", "20", "8"], "why": "10⁵ ≡ 1 on the clock of 41, and no smaller power: 02439."}, {"q": "2³⁴⁰ ≡ 1 (mod 341). Is 341 prime?", "a": "no: 341 = 11 · 31", "w": ["yes", "it cannot be told", "only if 3³⁴⁰ ≡ 1 too"], "why": "The little technique runs one way."}, {"q": "Which technique of rung 19 does the little technique spend?", "a": "order-divides: a member to the size of the group is e", "w": ["socks and shoes", "the part-group test", "every group of prime size turns about"], "why": "19d5, in the units of the clock of p."}, {"q": "How many units has the clock of pq, p and q different primes?", "a": "(p − 1)(q − 1)", "w": ["pq − 1", "p + q", "pq − 2"], "why": "pq − q − p + 1; 43i builds a lock on it."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43e"]=[{"q": "What is a full hand of a clock?", "a": "a unit whose powers are every unit", "w": ["an hour whose square is 1", "a prime hour", "the hour [n − 1]"], "why": "Its accepted name is a primitive root."}, {"q": "[a] has order 12. What is the order of [a]⁸?", "a": "3", "w": ["8", "4", "12"], "why": "Power-order: 12/gcd(12, 8) = 3."}, {"q": "How many roots can a polynomial of degree d have on a prime clock?", "a": "at most d", "w": ["exactly d", "at most d − 1", "any number"], "why": "The few-roots technique."}, {"q": "How many roots has x² − 1 on the clock of 8?", "a": "4", "w": ["2", "1", "8"], "why": "1, 3, 5, 7: the clock of 8 is no field."}, {"q": "What do c(d) add to, over the divisors d of n?", "a": "n", "w": ["n − 1", "the count of units of n", "2n"], "why": "The divisor-sum technique."}, {"q": "How many full hands has the clock of 13?", "a": "4", "w": ["12", "2", "6"], "why": "c(12) = 4: [2], [6], [7], [11]."}, {"q": "How is [2] shown to be a full hand of the clock of 13?", "a": "2⁶ ≢ 1 and 2⁴ ≢ 1", "w": ["2¹² ≡ 1", "2 is prime", "2² ≢ 1"], "why": "Test the powers (p − 1)/q for each prime q ∣ 12."}, {"q": "Which clock has no full hand?", "a": "8", "w": ["7", "9", "13"], "why": "Every unit of the clock of 8 squared is [1]."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43f"]=[{"q": "How many units of the clock of an odd prime p are squares?", "a": "(p − 1)/2", "w": ["p − 1", "√p", "one"], "why": "The half-squares technique: they pair as ±x."}, {"q": "What is a^((p − 1)/2) on the clock of p, for p ∤ a?", "a": "(a ∕ p), that is ±1", "w": ["always 1", "a", "0"], "why": "The square-test technique."}, {"q": "Is −1 a square on the clock of 13?", "a": "yes", "w": ["no", "only on the clock of 7", "it has no mark"], "why": "13 ≡ 1 (mod 4): 5² = 25 ≡ −1."}, {"q": "On the clock of 7, which of 2, 4, 6 land high?", "a": "4 and 6", "w": ["2 only", "all three", "none"], "why": "Above 7/2; μ = 2, so 2 is a square there."}, {"q": "3 and 7 are both 3 (mod 4). How do (3 ∕ 7) and (7 ∕ 3) compare?", "a": "they have opposite signs", "w": ["they are equal", "both are 0", "both are 1"], "why": "The square-swap technique."}, {"q": "Is 219 a square on the clock of 383?", "a": "yes", "w": ["no", "only if 383 ≡ 1 (mod 4)", "it cannot be decided without a search"], "why": "By swapping: (219 ∕ 383) = 1; a root is 169."}, {"q": "What is ⌊17/5⌋?", "a": "3", "w": ["3.4", "4", "2"], "why": "The whole part, laid down in 43f4."}, {"q": "Can the square-swap technique be used on 15 and 7 as they stand?", "a": "no: 15 is not prime", "w": ["yes", "yes, with a minus sign", "only if 15 ≡ 1 (mod 4)"], "why": "Split 15 = 3 · 5 first."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43g"]=[{"q": "Does the sum of 1/p over the primes settle?", "a": "no, it passes every bound", "w": ["yes, near 2", "yes, near ln 2", "it is not known"], "why": "The thin-but-endless technique: at least ln ln x − 1."}, {"q": "ζ(s) for s > 1 is the endless product over primes of what?", "a": "1/(1 − p^(−s))", "w": ["1 − p^(−s)", "1/p^s", "1 + 1/p"], "why": "The prime-product technique."}, {"q": "What does π(x) name on this rung?", "a": "the number of primes at most x", "w": ["the round number times x", "the product of the primes up to x", "the largest prime below x"], "why": "Laid down in 43g3."}, {"q": "Which is proved on 43g, and which held in trust?", "a": "the fence from the middle count is proved; π(x) ≈ x/ln x is held in trust", "w": ["both proved", "both held in trust", "the prime count is proved; the fence is held in trust"], "why": "The prime-count technique is held in trust."}, {"q": "Which hours of the clock of 4 hold endlessly many primes, by the four-clock technique?", "a": "[1] and [3]", "w": ["[1] only", "[2]", "every hour"], "why": "Two lists and one square test."}, {"q": "A prime r divides (2q₁⋯q_k)² + 1. What is r on the clock of 4?", "a": "[1]", "w": ["[3]", "[2]", "it can be anything"], "why": "−1 is a square on its clock, so r ≡ 1 (mod 4)."}, {"q": "Does π(x) ≈ x/ln x mean their difference shrinks?", "a": "no, the ratio settles on 1", "w": ["yes", "only past 10⁹", "only below a million"], "why": "At 10⁹ the gap is over 2.5 million."}, {"q": "About what share of numbers near 10¹⁰⁰ are prime?", "a": "one in 230", "w": ["one in 100", "one in 10", "one in 10⁵⁰"], "why": "ln 10¹⁰⁰ ≈ 230."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43h"]=[{"q": "What are the last three digits of 3²¹⁸?", "a": "489", "w": ["218", "387", "561"], "why": "Square-and-multiply on the clock of 1000."}, {"q": "218 written in twos?", "a": "11011010", "w": ["10110110", "11101010", "11011001"], "why": "128 + 64 + 16 + 8 + 2."}, {"q": "About how many products does square-and-multiply need for an exponent below 10³⁰⁰?", "a": "about 2000", "w": ["about 10³⁰⁰", "about 300", "about 600 000"], "why": "At most 2 log₂ k, log₂ k < 997."}, {"q": "In the gcd algorithm, each remainder is less than what?", "a": "half of the one two rounds before", "w": ["half of the one before", "a third of the first", "the quotient"], "why": "The halving-remainders technique."}, {"q": "Why may 402 not be cut to 2 in 2⁴⁰² on the clock of 1000?", "a": "2 is no unit of the clock of 1000", "w": ["402 is even", "1000 is not prime", "it may be"], "why": "2⁴⁰² ≡ 504."}, {"q": "Which pairs make the gcd algorithm slowest?", "a": "neighbours in 1, 1, 2, 3, 5, 8, …", "w": ["two primes", "a number and its double", "two powers of 2"], "why": "Every quotient is 1."}, {"q": "Why reduce on the clock after every product?", "a": "so no number passes n²", "w": ["to keep the exponent small", "because the order matters", "to cut the exponent"], "why": "3¹²⁸ alone has 62 digits."}, {"q": "3²¹⁸ on the clock of 8?", "a": "1", "w": ["3", "9", "0"], "why": "c(8) = 4 and 218 ≡ 2: 3² = 9 ≡ 1."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43i"]=[{"q": "With p = 61 and q = 53, what is c?", "a": "3120", "w": ["3233", "3232", "114"], "why": "(61 − 1)(53 − 1)."}, {"q": "With e = 17 and c = 3120, what is the home key d?", "a": "2753", "w": ["17", "3233", "413"], "why": "17 · 2753 = 46 801 = 15 · 3120 + 1."}, {"q": "On which clock must d undo e?", "a": "the clock of c", "w": ["the clock of n", "the clock of e", "the clock of p"], "why": "Exponents live on the clock of the count of units."}, {"q": "What does the count-gives-factors technique give from n and c?", "a": "p and q, as roots of a quadratic", "w": ["d", "the signature", "nothing new"], "why": "n − c + 1 = p + q."}, {"q": "How is m signed?", "a": "s = m^d on the clock of n", "w": ["s = m^e", "s = m + d", "s = m^c"], "why": "The turned-key technique."}, {"q": "How does anyone check a signature s on m?", "a": "s^e ≡ m", "w": ["s^d ≡ m", "s ≡ m", "s^c ≡ 1"], "why": "The printed key unlocks what the home key locked."}, {"q": "Why does a small m locked with e = 3 give itself away?", "a": "m³ < n is not reduced, so an ordinary cube root finds m", "w": ["3 is prime", "d is small", "m shares a prime with n"], "why": "The clock never wraps."}, {"q": "How many products does locking with e = 65 537 take?", "a": "17", "w": ["65 537", "2", "33"], "why": "2¹⁶ + 1: sixteen squarings and one product."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43j"]=[{"q": "What does a witness a with a^(n − 1) ≢ 1 (mod n) prove?", "a": "n is composite", "w": ["n is prime", "a is a factor of n", "nothing"], "why": "The little technique backwards."}, {"q": "Which number lies for every base sharing nothing with it?", "a": "561", "w": ["341", "91", "2047"], "why": "3 · 11 · 17, and 2, 10, 16 divide 560."}, {"q": "On a prime clock, what are the square roots of [1]?", "a": "±[1] only", "w": ["four of them", "[1] only", "every unit"], "why": "Few roots: x² − 1 has at most two."}, {"q": "The strong test chain for 561, base 2: 263, 166, 67, 1. What factor does it hand over?", "a": "33", "w": ["3", "17", "67"], "why": "gcd(67 − 1, 561) = 33."}, {"q": "At most what share of bases are strong liars for an odd composite?", "a": "a quarter", "w": ["a half", "none", "one in n"], "why": "Held in trust here, proved in 1980."}, {"q": "What does the strong test say after 50 rounds passed?", "a": "prime, with an exception rate below 4⁻⁵⁰", "w": ["prime, for certain", "composite", "nothing"], "why": "The green box: laws with a known exception rate."}, {"q": "Which test is never fooled, by (x + a)ⁿ against xⁿ + a?", "a": "the binomial test", "w": ["the little test", "the strong test", "the root bound"], "why": "Prime exactly when every coefficient agrees on the clock of n."}, {"q": "A composite n has a prime factor at most what?", "a": "√n", "w": ["n/2", "ln n", "n/3"], "why": "The root-bound technique."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43k"]=[{"q": "What is 1071/462 as a staircase?", "a": "[2; 3, 7]", "w": ["[2; 7, 3]", "[3; 2, 7]", "[2; 3, 21]"], "why": "The gcd algorithm’s quotients."}, {"q": "What do neighbouring convergents cross-multiply to differ by?", "a": "1", "w": ["0", "their steps", "the next bottom"], "why": "The neighbour technique: (−1)^(j − 1)."}, {"q": "Why is every convergent in lowest terms?", "a": "a common divisor of p_j and q_j divides ±1", "w": ["the steps are whole", "the bottoms grow", "the gcd algorithm stops"], "why": "From the neighbour technique."}, {"q": "How close does a convergent p/q of a number that is no fraction come?", "a": "within 1/q²", "w": ["within 1/q", "exactly", "within 1/(2q)"], "why": "The convergent-bound technique."}, {"q": "Which large step after 355/113 makes it so close to π?", "a": "292", "w": ["15", "7", "16"], "why": "π = [3; 7, 15, 1, 292, …]."}, {"q": "Why twelve notes to the octave?", "a": "12 is a bottom of a convergent of log₂ 3", "w": ["12 = 2² · 3", "the ear has twelve sensors", "by 6·phys’s comma alone"], "why": "Equal steps fit a fifth when the bottom is a convergent’s."}, {"q": "The least answer of x² − 3y² = 1?", "a": "(2, 1)", "w": ["(7, 4)", "(1, 0)", "(5, 3)"], "why": "4 − 3 = 1; the unit-climb then gives (7, 4), (26, 15)."}, {"q": "What does the unit-climb technique do?", "a": "powers of x₁ + y₁√n give new answers", "w": ["adds answers", "halves answers", "finds the least answer"], "why": "The sizes multiply."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43l"]=[{"q": "What is log₅ 8 on the clock of 23?", "a": "6", "w": ["8", "3", "11"], "why": "5⁶ ≡ 8."}, {"q": "On which clock do clock logs add?", "a": "the clock of p − 1", "w": ["the clock of p", "the clock of g", "no clock"], "why": "The clock-log technique."}, {"q": "A and B are sent; what do both sides reach?", "a": "g^(ab)", "w": ["g^(a + b)", "AB", "a + b"], "why": "The shared-secret technique."}, {"q": "With p = 23, g = 5, A = 8, B = 19, what is the shared hour?", "a": "2", "w": ["8", "19", "6"], "why": "19⁶ ≡ 2."}, {"q": "About how many products does step-and-stride take?", "a": "about 2√p", "w": ["about p", "about log p", "about p²"], "why": "Two lists of about √p."}, {"q": "When does the split-log technique help most?", "a": "when p − 1 has only small prime factors", "w": ["when p − 1 = 2q with q prime", "when g = 2", "never"], "why": "Logs split onto small clocks."}, {"q": "What is log₂ 10 on the clock of 37?", "a": "24", "w": ["10", "36", "6"], "why": "Read as 0 on the clock of 4 and 6 on the clock of 9."}, {"q": "Can the exchange alone stop a listener who changes messages?", "a": "no", "w": ["yes", "yes, with a large p", "yes, if g is a full hand"], "why": "She stands in the middle; each side must sign."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43·cb19"]=[{"q": "What is the copy a + 12ℤ?", "a": "the hour [a] of the clock of 12", "w": ["a times 12", "a part-group", "the multiples of a"], "why": "b is in it exactly when b ≡ a (mod 12)."}, {"q": "When do copies of H multiply by (aH)(bH) = abH?", "a": "exactly when gH = Hg for every g", "w": ["always", "exactly when H is finite", "exactly when G turns about"], "why": "The copies-combine technique; such H is normal."}, {"q": "Is {e, s₁₂} normal in S₃?", "a": "no", "w": ["yes", "only for even shuffles", "it is not a part-group"], "why": "s₁₃{e, s₁₂} ≠ {e, s₁₂}s₁₃."}, {"q": "What is K, for a product-keeping map f?", "a": "the members sent to e′", "w": ["the image", "the undos", "the copies"], "why": "The sent-to-e technique makes it normal."}, {"q": "Why are the even shuffles normal in Sₙ?", "a": "they are what the sign map sends to +1", "w": ["they turn about", "there are half of them, always", "by counting"], "why": "The sent-to-e technique."}, {"q": "G/K matches what?", "a": "the image of f", "w": ["G", "K", "the free group"], "why": "The image-matching technique."}, {"q": "The units of a prime clock under times match what?", "a": "the clock of p − 1 under adding", "w": ["the clock of p", "ℤ", "the clock of 2"], "why": "The clock log, by image-matching."}, {"q": "Does gH = Hg give gh = hg for each h?", "a": "no", "w": ["yes", "only in S₃", "only for H normal"], "why": "The sets agree, not the members."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["43·cb7"]=[{"q": "From the clock of 10ᵏ, how many counts of units reach the clock of 1?", "a": "3k", "w": ["k", "2k", "10ᵏ"], "why": "k steps take the 5s out, 2k halve the 2s: the clock-chain technique."}, {"q": "What are the last ten digits of 3↑↑↑3?", "a": "2464195387", "w": ["5597484987", "6464195387", "7625597484987"], "why": "Frozen from towers of 11 threes."}, {"q": "From which height do the last three digits of 3↑↑b freeze?", "a": "b = 4", "w": ["b = 2", "b = 3", "b = 10"], "why": "3↑↑3 ends in 987, 3↑↑4 in 387."}, {"q": "What is the order of [3] on the clock of 1000?", "a": "100", "w": ["400", "1000", "20"], "why": "Orders may stand in for counts of units."}, {"q": "What does x mod m name?", "a": "the remainder of x on dividing by m, from 0 to m − 1", "w": ["the clock of m", "x divided by m", "the hour [m]"], "why": "Laid down on 43·cb7."}, {"q": "Do clocks give the first digit of 3↑↑↑3?", "a": "no", "w": ["yes", "yes, by the tower-freeze technique", "only its parity"], "why": "The first digit is a question about size."}, {"q": "What are the last two digits of a tall tower of sevens?", "a": "43", "w": ["07", "49", "01"], "why": "7⁷ = 823 543, frozen from b = 2."}, {"q": "Which condition does the chain need of the base?", "a": "it is a unit of every clock in the chain", "w": ["it is prime", "it is odd", "it is below 10"], "why": "For the exponent-clock technique at each level."}];

