(window.LADDER_CARDS=window.LADDER_CARDS||{})["43·cb37"]=[{"q": "In twelve equal steps from A, which hour is E?", "a": "[7]", "w": ["[5]", "[4]", "[8]"], "why": "A, B is [2], C [3], D [5], E [7]."}, {"q": "A tune moved up a fifth. What happens to every note on the clock of 12?", "a": "[7] is added", "w": ["it is multiplied by 7", "it is doubled", "[5] is taken away and the octave kept"], "why": "The pitch-clock technique."}, {"q": "Stacked fifths on the clock of 12 reach how many notes?", "a": "all 12", "w": ["7", "6", "3"], "why": "gcd(7, 12) = 1."}, {"q": "Stacked minor thirds on the clock of 12 reach how many notes?", "a": "4", "w": ["3", "12", "6"], "why": "12/gcd(3, 12)."}, {"q": "Which intervals of the clock of 12 walk through every note?", "a": "1, 5, 7 and 11 steps", "w": ["every interval", "only 7", "the even ones"], "why": "The units of the clock of 12."}, {"q": "Tones of t steps and semitones of s. What is the clock?", "a": "5t + 2s", "w": ["7t", "t + s", "12t"], "why": "Five tones and two semitones to the octave."}, {"q": "In the tuning of 53 steps, how big are the tone and the semitone?", "a": "9 and 4 steps", "w": ["2 and 1", "53 and 26", "8 and 4"], "why": "5 · 9 + 2 · 4 = 53."}, {"q": "Quarter tones, t = 4 and s = 2. How many of the 24 notes do fifths reach?", "a": "12", "w": ["24", "2", "6"], "why": "gcd(4, 2) = 2."}, {"q": "A 3-beat figure over 4-beat bars. When does it start with a bar again?", "a": "after 12 beats", "w": ["after 7 beats", "after 4 beats", "never"], "why": "lcm(3, 4)."}, {"q": "A 6-beat figure over 4-beat bars. When does it start with a bar again?", "a": "after 12 beats", "w": ["after 24 beats", "after 10 beats", "after 6 beats"], "why": "lcm(6, 4) = 24/2."}];
(window.LADDER_CARDS["43·cb19"]=window.LADDER_CARDS["43·cb19"]||[]).push(...[{"q": "H a part-group of G, N normal in G. What does HN/N match?", "a": "H/(H ∩ N)", "w": ["H/N", "N/(H ∩ N)", "HN"], "why": "43·cb19.5: the part-and-normal technique."}, {"q": "Under adding, H = 4ℤ and N = 6ℤ. What are H + N and H ∩ N?", "a": "2ℤ and 12ℤ", "w": ["10ℤ and 24ℤ", "2ℤ and 24ℤ", "1ℤ and 12ℤ"], "why": "43·cb19.5: so 2ℤ/6ℤ matches 4ℤ/12ℤ, three copies each."}, {"q": "N normal in G. The part-groups of G/N are?", "a": "M/N, for the part-groups M of G that hold N", "w": ["every set of copies", "M/N, for every part-group M of G", "only the normal ones"], "why": "43·cb19.6: the quotient-parts technique."}, {"q": "How many part-groups does the clock of 12 have?", "a": "6", "w": ["12", "4", "2"], "why": "43·cb19.6: one for each d dividing 12."}]);
/* phase F und_r43: understanding cards, appended (ids follow the deck's own) */
(window.LADDER_CARDS["43a"]=window.LADDER_CARDS["43a"]||[]).push(
 {"u":"43a1.1","q":"What does m ≡ b (mod n) mean, and what is the modulus? What does the difference-test technique say, and why is the multiple of n in its last line 0?","a":"It means that n divides m − b, read “m is b on the clock of n”, and n is the modulus, the length of one turn of the clock; two counting numbers leave the same remainder on dividing by n exactly when n divides their difference; the difference r − t of the two remainders lies strictly between −n and n, and the only multiple of n there is 0, since nk with k ≠ 0 has size at least n","w":["It means that m divides b; the modulus is the remainder; two numbers have the same remainder when their sum is a multiple of n; the multiple is 0 because remainders are 0","It means that n divides m + b; the modulus is n; the difference test says n divides m and b; the multiple is 0 because m = b","It means that m and b are equal; the modulus is the quotient; the difference test fails for negatives; the multiple is n"],"why":"38 ≡ 14 (mod 12), and −1 ≡ 11 (mod 12)."},
 {"u":"43a2.1","q":"What is ℤ/n, and why does it have exactly n members? What does the carry-to-the-clock technique say, and which line of its proof needed taking away?","a":"The quotient set of ℤ by ≡ (mod n), the hours of the clock of n: nothing is divided; every integer lies in one of [0], [1], …, [n − 1], by division with remainder, and no two of those are the same class; if m ≡ m′ and b ≡ b′ (mod n) then m + b ≡ m′ + b′ and mb ≡ m′b′ (mod n); the line mb − m′b′ = m(b − b′) + b′(m − m′) needed taking away","w":["ℤ divided by n, the fractions k/n; it has n members because n is counted n times; sums carry over but products do not; no line needs taking away","The set of multiples of n; it has endlessly many members; the technique says m ≡ m′ gives mᵇ ≡ m′ᵇ′; the first line needed taking away","The set of classes of ≡ (mod n); it has n − 1 members, since [0] is left out; the technique carries sums and products; the line for sums needed taking away"],"why":"So [m] + [b] = [m + b] and [m][b] = [mb] are honest on ℤ/n."},
 {"u":"43a3.1","q":"What does the equations-come-along technique say, and why does every technique that is an equation between integers come along? Why does order not come along?","a":"Every technique of plus and times that is an equation between integers is true of the hours of every clock; the class map keeps both operations, so the class of one side of the equation is the class of the other; “less than” is not a statement about hours: on the clock of 12, [11] + [1] = [0], and adding [1] twelve times comes back to the start, so no order keeps adding honest","w":["Only turn-about comes along; the rest fail because clocks are finite; order comes along on prime clocks","Every technique of plus, times and order is true of the hours; order comes along because [0] is least","Every equation comes along because hours are integers; order fails only on the clock of 12"],"why":"Casting out nines is one line about 10 ≡ 1 (mod 9)."},
 {"u":"43a4.1","q":"What does the clock-cancel technique say? Which [a] on the clock of 10 can be cancelled, and why can [4] not be?","a":"On the clock of n, [a][x] = [a][y] always gives [x] = [y] exactly when gcd(a, n) = 1; on the clock of 10 these are [1], [3], [7], [9]; gcd(4, 10) = 2, and [4][5] = [20] = [0] = [4][0] while [5] ≠ [0]","w":["Cancelling [a] works whenever [a] ≠ [0]; every hour of the clock of 10 but [0] can be cancelled; [4] can be","Cancelling works exactly when a divides n; the hours [1], [2], [5] can be cancelled; [4] fails because 4 does not divide 10","Cancelling works exactly when gcd(a, n) = 1; the hours [1], [3], [5], [7], [9] can be cancelled; [4] fails because it is even"],"why":"The hours that share a divisor above 1 with the clock multiply some other hour to [0]."},
 {"u":"43a5.1","q":"Why does 1 ≡ 6 (mod 5) not give 2¹ ≡ 2⁶ (mod 5)? Why does halving 14 ≡ 2 (mod 12) not give 7 ≡ 1 (mod 12)?","a":"The class of the base carries over, but the exponent is a count and does not: 2 against 64 ≡ 4; and 12 does not divide 7 − 1 = 6: halving both sides halves the clock too, 7 ≡ 1 (mod 6)","w":["It does give it, since 2⁶ = 64 ≡ 2; and halving is always allowed","The exponent carries and the base does not; and 7 ≡ 1 (mod 12) is right","Powers are not defined on clocks; and 14 ≡ 2 (mod 12) is false to begin with"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43b"]=window.LADDER_CARDS["43b"]||[]).push(
 {"u":"43b1.1","q":"What does the gcd-as-a-sum technique say, and how does it come from 4j13? What does the undo-exactly-when technique say, and why is the undo only one?","a":"For any integers a and n, not both 0, there are integers x and y with ax + ny = gcd(a, n); it is 4j13 with the multiple taken across, which 4j13 could not do without taking away; the hour [a] has an undo on the clock of n exactly when gcd(a, n) = 1, and then only one, since [a][x] = [a][x′] gives [x] = [x′] by the clock-cancel technique","w":["There are x and y with ax + ny = 1 for every a and n; it is 4j12; every hour but [0] has an undo; the undo is one because n is prime","There are x and y with ax = ny; it is 4j13 unchanged; [a] has an undo exactly when a divides n; there may be several","There are x and y with ax + ny = gcd(a, n); it is new to this rung; [a] has an undo when gcd(a, n) > 1; the undo is one by order"],"why":"The same line, ax + ny = 1, says both cancel and undo."},
 {"u":"43b2.1","q":"How is the undo of [17] on the clock of 43 found from the gcd algorithm? Why is [17]⁻¹ not 5b’s reciprocal of 17?","a":"Run the algorithm, 43 = 17 · 2 + 9, 17 = 9 + 8, 9 = 8 + 1, and read it from the foot up: 1 = 9 − 8 = 2 · 9 − 17 = 2 · 43 − 5 · 17, so 17 · (−5) ≡ 1 and [17]⁻¹ = [−5] = [38]; 1/17 is no integer and names no hour, while [17]⁻¹ is the hour [38]","w":["Divide 43 by 17 and round: the undo is [3]; it is the reciprocal, written on the clock","Try 17 · k for each k until 43 appears; the undo is [26]; it differs from 1/17 only in sign","The undo is [43 − 17] = [26]; it is 5b’s reciprocal because 17 · 1/17 = 1"],"why":"Check: 17 · 38 = 646 = 15 · 43 + 1."},
 {"u":"43b3.1","q":"What is a unit, and what does (ℤ/n)ˣ name? What does the units-group technique say, and where does 19c enter its proof?","a":"A unit is an hour with an undo, and (ℤ/n)ˣ is the set of them; the units of the clock of n form a group under times; 19c shows that a product of units is a unit: [b]⁻¹[a]⁻¹ undoes [a][b]","w":["A unit is the hour [1]; (ℤ/n)ˣ is the clock without [0]; the units form a group under plus; 19c gives the undo of [1]","A unit is an hour with an undo; (ℤ/n)ˣ names the units; the units form a field; 19c shows that regroup holds","A unit is a prime hour; (ℤ/n)ˣ is the set of primes below n; they form a group only when n is prime; 19c is not used"],"why":"The clocks of 12 and 10 each have four units, and the two groups are not alike."},
 {"u":"43b4.1","q":"What does the prime-clock-field technique say? Why is the clock of 15 not a field, and how is 17x ≡ 5 (mod 43) solved?","a":"The clock of n is a field exactly when n is prime; 15 = 3 · 5, so [3][5] = [0] and [3] has no undo; on the clock of 43, x = [17]⁻¹ · 5 = 38 · 5 = 190 ≡ 18, and 17 · 18 = 306 = 7 · 43 + 5","w":["Every clock is a field; the clock of 15 is one too; 17x ≡ 5 is solved by x = 5/17","The clock of n is a field exactly when n is odd; 15 fails because it is too large; x = 5 − 17 = −12","The clock of n is a field exactly when n is prime; 15 fails because [0] = [1] there; x ≡ 38"],"why":"For each prime p there is a field with p members."},
 {"u":"43b5.1","q":"Why does [6] have no undo on the clock of 9? Why are the units of the clock of 12 not all the hours but [0]?","a":"gcd(6, 9) = 3, and [6][3] = [0]; and every hour but [0] is a unit only on a prime clock: the clock of 12 has four units, not eleven","w":["[6] has the undo [3]; and the clock of 12 has eleven units","6 is even; and the clock of 12 has six units, the odd hours","[6] is its own undo; and the units of 12 are the primes below 12"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43c"]=window.LADDER_CARDS["43c"]||[]).push(
 {"u":"43c1.1","q":"What does the remainder technique say? Which line of its proof needs m and n to share nothing, and why does onto come free?","a":"If m and n share no divisor above 1, reading an hour of the clock of mn on the clocks of m and n is a matching of ℤ/mn with the pairs ℤ/m × ℤ/n; the line from m ∣ nk to m ∣ k needs gcd(m, n) = 1, by factor-that-shares-nothing (5h); both sets have mn members, and a one-to-one map between finite sets of one size misses nothing","w":["Reading on two clocks is a matching for every m and n; no line needs them to share nothing; onto is proved by building each answer","If m and n share nothing, ℤ/mn has m + n members; the first line needs it; onto fails in general","If m and n share nothing the reading is one-to-one but not onto; the last line needs it; onto needs a separate search"],"why":"The proof says the answer exists; the next footing finds it."},
 {"u":"43c2.1","q":"How is the number 70 found, and what is it on each of the clocks of 3, 5 and 7? How does the footing put the leftovers 2, 3, 2 back together into 23?","a":"N/3 = 35 is 2 on the clock of 3, where [2]⁻¹ = [2], so e₃ = 35 · 2 = 70, which is 1 on the clock of 3 and 0 on the clocks of 5 and 7; with e₅ = 21 and e₇ = 15, x = 2 · 70 + 3 · 21 + 2 · 15 = 233 ≡ 23 (mod 105)","w":["70 is 2 · 35, chosen at random; it is 0 on the clock of 3; the leftovers are added: 2 + 3 + 2 = 7","70 is the least common multiple of 5 and 7 doubled; it is 1 on all three clocks; x = 70 + 21 + 15 = 106 ≡ 1","70 = 105 − 35; it is 2 on the clock of 3; x = 2 · 3 · 2 = 12"],"why":"The three numbers 70, 21 and 15 serve every list of leftovers on these clocks."},
 {"u":"43c3.1","q":"What does the two-clock technique say about sums, products and units? Why does x² ≡ 1 have four answers on the clock of 15?","a":"If m and n share nothing, the reading sends sums to sums and products to products, so an hour of the clock of mn is a unit exactly when both its readings are, and the counts of units multiply; x² ≡ 1 reads as x ≡ ±1 on the clock of 3 and x ≡ ±1 on the clock of 5: four pairs, so four answers, 1, 4, 11 and 14","w":["The reading keeps sums only; units are counted by adding; x² ≡ 1 has four answers because 15 has four divisors","The reading keeps sums and products; an hour is a unit when either reading is; x² ≡ 1 has two answers on every clock","The reading keeps products only; the units of mn are m + n; x² ≡ 1 has four answers because 4² = 16"],"why":"On a prime clock x² ≡ 1 has two answers; 43j turns the extra ones into a test."},
 {"u":"43c4.1","q":"What does the shared-divisor technique say? Why do x ≡ 1 (mod 4) and x ≡ 2 (mod 6) have no answer together?","a":"x ≡ a (mod m) and x ≡ b (mod n) together have an answer exactly when a ≡ b (mod gcd(m, n)), and then all the answers are one hour on the clock of the least common multiple; here gcd(4, 6) = 2 and 1 and 2 differ on the clock of 2: x would be odd on one clock and even on the other","w":["Two clocks always have a shared answer; the pair 1 and 2 has the answer 8","They have an answer exactly when m divides n; 4 does not divide 6","They have an answer exactly when a = b; 1 ≠ 2"],"why":"A rhythm of 260 days and a year of 365 share 5 and repeat every 18 980 days."},
 {"u":"43c5.1","q":"Why does the clock of 4 not match the pairs from the clocks of 2 and 2? Why do x ≡ 1 (mod 4) and x ≡ 1 (mod 6) not give x ≡ 1 (mod 24)?","a":"4 and 2 share 2: [1] + [1] ≠ [0] on the clock of 4, while every pair added to itself gives (0, 0); and the clocks of 4 and 6 share 2, so the answers are one hour on the clock of 12: 1 and 13 both work","w":["They do match, since both have four members and keep plus; and x ≡ 1 (mod 24) is right","The clock of 4 has more members; and the answers are one hour on the clock of 10","Pairs cannot be added; and 4 and 6 share nothing"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43d"]=window.LADDER_CARDS["43d"]||[]).push(
 {"u":"43d1.1","q":"What does the little technique say? Which technique of rung 19 does its proof spend, and in which group?","a":"If p is prime and p does not divide a, then a^(p − 1) ≡ 1 (mod p), and aᵖ ≡ a (mod p) for every integer a; the proof spends order-divides (19d5) in the group of units of the clock of p, which has p − 1 members","w":["If p is prime then a^p ≡ 1 (mod p); it spends 19a in the group of all hours under plus","If a^(p − 1) ≡ 1 (mod p) then p is prime; it spends 19c in the group of shuffles","If p does not divide a then a^(p − 1) ≡ a; it spends 19f in the symmetries of the p-gon"],"why":"2¹⁰⁰ on the clock of 101 is 1, though 2¹⁰⁰ has 31 digits."},
 {"u":"43d2.1","q":"What does the unit-count technique say? Why does the clock of a prime power pᵏ have pᵏ − pᵏ⁻¹ units?","a":"If n is the product of the prime powers p₁^(k₁), …, pᵣ^(kᵣ), the clock of n has n(1 − 1/p₁)⋯(1 − 1/pᵣ) units; on the clock of pᵏ an hour fails exactly when p divides it, and the multiples of p among 1, …, pᵏ number pᵏ⁻¹","w":["The clock of n has n − 1 units; a prime power has pᵏ − 1, since only [0] fails","The clock of n has n/2 units; a prime power has pᵏ⁻¹ units, the multiples of p","The clock of n has as many units as n has divisors; a prime power has k + 1"],"why":"The clock of 360 has 96 units, and the clock of pq has (p − 1)(q − 1)."},
 {"u":"43d3.1","q":"What does the exponent-clock technique say? Why may the exponent of 7²²² be cut on the clock of 4, though 43a5 forbade cutting it on the clock of 10?","a":"If gcd(a, n) = 1 and c is the count of units of the clock of n, then a^c ≡ 1 (mod n), and a^k ≡ a^j (mod n) whenever k ≡ j (mod c); the clock of 10 has c = 4 units, and 222 = 4 · 55 + 2, so 7²²² ≡ 7² = 49 ≡ 9; the exponent carries to the clock of the count of units, not to the clock of n","w":["Exponents carry to the clock of n; 7²²² ≡ 7² because 222 ≡ 2 (mod 10)","If gcd(a, n) = 1 then a^n ≡ 1 (mod n); the exponent is cut on the clock of 4 because 4 divides 10 − 2","Exponents never carry to any clock; 7²²² must be multiplied out"],"why":"The power is cut twice: the base on the clock of n, the exponent on the clock of c."},
 {"u":"43d4.1","q":"What does the decimal-block technique say? Why is the block of 1/41 five digits long, and why must its length divide 40?","a":"If q shares nothing with 10, the decimal of 1/q repeats from the first place in a block whose length is the least k with 10ᵏ ≡ 1 (mod q), and that length divides the count of units of the clock of q; 10⁵ − 1 = 99 999 = 41 · 2439, so the block is 02439; the length is the order of [10], which divides the 40 units by order-divides (19d5)","w":["The block of 1/q is q − 1 digits long for every q; 1/41 has a block of 40","The block length is the least k with 10ᵏ ≡ 0 (mod q); 1/41 has five digits because 41 has two","The block length is q divided by 10; for 41 it is 5 after rounding; it divides 40 by chance"],"why":"Whether endlessly many primes q have a block q − 1 long is open."},
 {"u":"43d5.1","q":"Why does 2³⁴⁰ ≡ 1 (mod 341) not make 341 prime? Why may the exponent of 7²²² not be cut on the clock of 10?","a":"341 = 11 · 31: the little technique runs one way, from prime to the power, and not back; and the exponent goes on the clock of the count of units, 4, not of 10","w":["341 is prime, by the little technique run backwards; and the exponent may be cut on the clock of 10","2³⁴⁰ is not 1 on the clock of 341; and exponents are cut on the clock of 9","341 is even; and 7 is not a unit of the clock of 10"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43e"]=window.LADDER_CARDS["43e"]||[]).push(
 {"u":"43e1.1","q":"What is a full hand, or primitive root, of a clock? What does the power-order technique say, and why are [3] and [5] the full hands of the clock of 7?","a":"A unit whose powers are every unit, so a unit whose order is the count of units; if [a] has order m, then [a]ᵏ has order m/gcd(m, k); [3] is a full hand of the clock of 7, with 6 units, so [3]ᵏ is one exactly when gcd(k, 6) = 1, which is k = 1 and 5: [3] and [3]⁵ = [5]","w":["A unit whose square is [1]; [a]ᵏ has order mk; [3] and [5] are full hands because they are odd","An hour whose powers are every hour, [0] included; [a]ᵏ has order m − k; [3] and [5] are the only primes below 7","A unit of order 2; [a]ᵏ has order m/k for every k; [3] and [5] are full hands because 3 · 5 = 15 ≡ 1"],"why":"Two full hands: the count of units of the clock of 6."},
 {"u":"43e2.1","q":"What does the few-roots technique say, and which two facts of 9g’s proof does a prime clock supply? Why does x² − 1 have four roots on the clock of 8?","a":"On a prime clock, a polynomial of degree d whose leading coefficient is not [0] has at most d roots; a prime clock is a field, so it has undoes for the long division and no two nonzero hours multiplying to [0]; the clock of 8 is no field: at x = [3], (x − 1)(x + 1) = [2][4] = [0] with neither factor [0], and so [1], [3], [5], [7] are all roots","w":["On every clock a polynomial of degree d has exactly d roots; a prime clock supplies adding and taking away; x² − 1 has four roots on the clock of 8 because 8 is even","On a prime clock a polynomial has no roots; it supplies the order of a unit and the little technique; four roots because 8 = 2 · 4","On a prime clock a polynomial of degree d has at least d roots; it supplies long division only; four roots because x² − 1 has degree 4 there"],"why":"So the clock of 8 has no full hand."},
 {"u":"43e3.1","q":"What does the divisor-sum technique say? How are the n fractions k/n sorted in its proof, and how many get the bottom d?","a":"For every n ≥ 1, the counts of units c(d) of the clocks whose sizes d divide n add up to n; each of the fractions 1/n, 2/n, …, n/n is written in lowest terms, in exactly one way, and sorted by its bottom d, a divisor of n; the fractions with bottom d are the j/d with gcd(j, d) = 1, and they number c(d)","w":["The counts c(d) for every d ≤ n add up to n; the fractions are sorted by their tops; d of them get the bottom d","The counts c(d) over the divisors of n multiply to n; the fractions are sorted by size; one gets each bottom","c(n) = n for every n; the fractions are not sorted; n/d of them get the bottom d"],"why":"For n = 12: 1 + 1 + 2 + 2 + 2 + 4 = 12."},
 {"u":"43e4.1","q":"What does the full-hand technique say? Which line of its proof spends the few-roots technique, and how is [2] shown to be a full hand of the clock of 13?","a":"Every prime clock has a full hand, and the clock of p has exactly c(p − 1) of them; if [a] has order d, its d powers are different roots of x^d − 1, and by the few-roots technique they are all its roots, so every unit of order d is some [a]ᵏ; for 13, with 12 = 2² · 3, test the powers 12/2 and 12/3: 2⁶ ≡ 12 and 2⁴ ≡ 3, neither [1], so the order of [2] is 12","w":["Every clock has a full hand; the few-roots technique is spent on the divisor sum; [2] is a full hand of the clock of 13 because 2¹² ≡ 1","Every prime clock has exactly one full hand; the few-roots technique is spent on the last line; [2] is shown by listing 2, 4, 8","Every prime clock has p − 1 full hands; the few-roots technique is not used; [2] is a full hand because 2 is the least prime"],"why":"The full hands of the clock of 13 are [2], [6], [11], [7]: c(12) = 4."},
 {"u":"43e5.1","q":"Why does 2¹² ≡ 1 (mod 13) not show that [2] is a full hand? Why is the square of a full hand of an odd prime clock never a full hand?","a":"Every unit has [a]¹² = [1] on the clock of 13, by the little technique, so the test is the smaller powers 2⁶ and 2⁴; and gcd(2, p − 1) = 2 for odd p, so [a]² has order (p − 1)/2","w":["Because 2¹² is not 1 on that clock; and the square of a full hand is always [1]","Because only odd hours can be full hands; and squares are never units","Because 12 is not prime; and the square of a full hand is a full hand on every odd prime clock"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43f"]=window.LADDER_CARDS["43f"]||[]).push(
 {"u":"43f1.1","q":"What does the half-squares technique say, and why do the units pair off? What does the mark (a ∕ p) give, and why is it not a fraction?","a":"On the clock of an odd prime p exactly (p − 1)/2 of the units are squares, and they are the even powers of any full hand; [x]² = [y]² exactly when [x] = ±[y], since a prime clock has no zero product, and [x] ≠ −[x] since p is odd, so the units pair off as ±[x], each pair one square; the mark is +1 when [a] is a square unit, −1 when [a] is a unit and not a square, and 0 when p ∣ a: the round brackets are part of the mark","w":["Every unit of an odd prime clock is a square; the units pair off with their undoes; the mark gives a divided by p","Exactly (p − 1)/2 units are squares, the odd powers of a full hand; the units pair off as [x] and [x]²; the mark gives the square root of a on the clock of p","Half the hours, [0] included, are squares; the units pair off because p is even; the mark is the remainder of a by p"],"why":"So (3 ∕ 11) = +1 and (7 ∕ 11) = −1."},
 {"u":"43f2.1","q":"What does the square-test technique say? Why is −1 a square on the clock of 13 and not on the clock of 7?","a":"For an odd prime p and p ∤ a, a^((p − 1)/2) ≡ (a ∕ p) (mod p); so −1 is a square exactly when (p − 1)/2 is even, which is when p ≡ 1 (mod 4): 13 = 4 · 3 + 1, and 5² = 25 ≡ −1 there, while 7 ≡ 3 (mod 4), and on the clock of 7 no square is 6","w":["a^(p − 1) ≡ (a ∕ p) (mod p); −1 is a square on the clock of 13 because 13 is larger than 7","a^((p − 1)/2) ≡ 1 for every unit; −1 is a square on every prime clock, 7 included","a² ≡ (a ∕ p) (mod p); −1 is a square on the clock of 13 because 13 ≡ 3 (mod 4), and not on 7 because 7 ≡ 1 (mod 4)"],"why":"The mark multiplies too: (ab ∕ p) = (a ∕ p)(b ∕ p)."},
 {"u":"43f3.1","q":"What does the high-count technique say? Why are the folds r₁, …, r_h all different, and how does the count show 2 is a square on the clock of 7?","a":"For an odd prime p and p ∤ a, (a ∕ p) = (−1)^μ, where μ is the number of a, 2a, …, ha that land high on the clock of p; if two folds were equal then [ja] = ±[ka], so j = ±k after cancelling [a], and j + k lies between 2 and p − 1, so j = k; on the clock of 7 the multiples are 2, 4, 6, and 4 and 6 land high, so μ = 2 and (2 ∕ 7) = +1","w":["(a ∕ p) = μ; the folds differ because a is prime; on the clock of 7 all three multiples land high, so 2 is a square","(a ∕ p) = (−1)^μ, with μ the number of multiples that land low; the folds may repeat; 2 is a square on the clock of 7 because 2 < 7/2","(a ∕ p) = (−1)^h; the folds differ because they are the multiples themselves; on the clock of 7 one multiple lands high, so 2 is a square"],"why":"And 3² = 9 ≡ 2 on the clock of 7."},
 {"u":"43f4.1","q":"What does the square-swap technique say? What is counted in the box, and why does no point of the box lie on the line qx = py?","a":"For different odd primes p and q, (p ∕ q)(q ∕ p) = (−1) to the power ((p − 1)/2)((q − 1)/2): each is a square on the other’s clock in the same way, unless both are 3 more than a multiple of 4, and then exactly one is; the h_p h_q whole-number points of the box are counted, those below the line by columns and those above by rows; a point on the line would need p ∣ qx, so p ∣ x, and x < p","w":["(p ∕ q) = (q ∕ p) for all odd primes; the box counts the primes below p and q; no point is on the line because p and q are odd","(p ∕ q)(q ∕ p) = −1 always; the box counts the squares on both clocks; points on the line are counted twice","(p ∕ q)(q ∕ p) = (−1)^(p + q); the box counts the multiples that land high; no point is on the line because the box is square"],"why":"With 5 and 19 the power is even, and 5 ≡ 9² on the clock of 19."},
 {"u":"43f5.1","q":"How is 219 on the clock of 383 decided, and which step spends the square-swap technique with a minus sign? Why is no number 8k + 7 a sum of three squares?","a":"219 = 3 · 73, so the mark splits into (3 ∕ 383)(73 ∕ 383); 3 and 383 are both 3 more than a multiple of 4, so (3 ∕ 383) = −(383 ∕ 3) = −(2 ∕ 3) = 1, the swap with a minus sign; (73 ∕ 383) = (383 ∕ 73) = (18 ∕ 73) = (2 ∕ 73)(3 ∕ 73)² = 1; so 219 is a square; the squares on the clock of 8 are 0, 1 and 4, and three of them add to 0, 1, 2, 3, 4, 5 or 6 there, never 7","w":["By trying all 191 candidates; the minus sign comes at 73; 8k + 7 is not a sum of three squares because it is odd","By the square test alone; no swap has a minus sign; 8k + 7 is never a sum of three squares because 7 is prime","219 = 3 · 73 and both marks are −1, so 219 is no square; the minus sign comes from 2; the squares on the clock of 8 are 0, 1, 2 and 4"],"why":"The proof says a square root exists and does not find it."},
 {"u":"43f6.1","q":"Why is (3 ∕ 7) not (7 ∕ 3)? Why can the square-swap technique not be used on 15 and 7 as they stand?","a":"3 and 7 are both 3 more than a multiple of 4, so the signs differ: 7 ≡ 1 is a square on the clock of 3 while 3 is not one on the clock of 7; and the technique is for two odd primes, and 15 = 3 · 5, so split first","w":["They are equal, since both are primes; and the technique works on any two odd numbers","Because 7 is larger than 3; and 15 is even","Because 3 is a square on the clock of 7; and 15 and 7 share a factor"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43g"]=window.LADDER_CARDS["43g"]||[]).push(
 {"u":"43g1.1","q":"What does the thin-but-endless technique say? Which line spends 4j18’s one prime list, and why does the sum over n ≤ x beat ln x?","a":"For every x ≥ 3, the sum of 1/p over the primes p ≤ x is at least ln ln x − 1, so it passes every bound; multiplying out the product of geometric sums, one for each prime p ≤ x, gives 1/n for each n ≤ x, since each such n has one prime list with all its primes ≤ x; and the sum of 1/n beats the area under 1/t, which is ln x","w":["The sum of 1/p settles below 2; the one prime list is spent on the last line; the sum over n beats ln x because 1/n > ln n","The sum of 1/p over p ≤ x is at least ln x; the one prime list shows the primes are endless; the sum over n equals ln x exactly","The sum of 1/p² passes every bound; the one prime list is not used; the sum over n beats ln x by the binomial technique"],"why":"Below a million the sum is about 2.89."},
 {"u":"43g2.1","q":"What does ζ(s) name, and what does the prime-product technique say? Why may the product of geometric sums be multiplied out in any order?","a":"ζ(s) = 1 + 1/2ˢ + 1/3ˢ + ⋯ on s > 1, which settles by the p-sums; for every s > 1, ζ(s) is the endless product over the primes of 1/(1 − p^(−s)); the terms are never negative, so the order is free, and each n comes once by its one prime list","w":["ζ(s) is the count of primes up to s; it is the sum over primes of 1/pˢ; the order is free because the product is finite","ζ(s) is a point running round a circle; it is the product over all n of 1/(1 − n^(−s)); the order is free because s > 1","ζ(s) = 1 + 2ˢ + 3ˢ + ⋯; it is the product over the primes of (1 − p^(−s)); the order matters and is fixed by size"],"why":"At s = 2 the product of (1 − 1/p²) is 6/π², about 0.6079."},
 {"u":"43g3.1","q":"What does the middle-count technique say? Why does every prime power dividing the middle count of choices stay at most 2n?","a":"For every n ≥ 1, π(2n) · ln(2n) ≥ n ln 4 − ln(2n + 1); the power of p in the middle count is the sum over j of ⌊2n/pʲ⌋ − 2⌊n/pʲ⌋, each term 0 or 1 and 0 when pʲ > 2n, so the power k is at most the number of j with pʲ ≤ 2n, and pᵏ ≤ 2n","w":["π(2n) = n ln 4; a prime power dividing the middle count is at most 2n because the count itself is below 2n","π(2n) · ln(2n) ≤ ln(2n + 1); every prime power is at most 2n because each prime divides the count once","π(2n) ≥ 4ⁿ; the prime powers stay at most 2n because primes above n do not divide the count"],"why":"For n = 50 the fence gives π(100) ≥ 14; the truth is 25."},
 {"u":"43g4.1","q":"What do the prime-count technique and fair shares claim, and which of them does the step prove? In the four-clock technique, why must a prime factor of (2q₁⋯q_k)² + 1 be 1 more than a multiple of 4?","a":"That π(x) divided by x/ln x settles on 1, and that when gcd(a, n) = 1 the hour [a] of the clock of n holds endlessly many primes, each unit hour getting the same share in the long run; both are held in trust, and the step proves whole only the hours [1] and [3] of the clock of 4; a prime r dividing that number is odd and has −1 ≡ (2q₁⋯q_k)² (mod r), so −1 is a square on the clock of r, and by the square test r ≡ 1 (mod 4)","w":["That π(x) = x/ln x exactly, and that every hour holds endlessly many primes; the step proves both; the factor is 1 more than a multiple of 4 because the number is","That the primes are endless, and that each clock has one prime; the step proves neither; the factor is in [1] because it is one of the qᵢ","That π(x) settles on 1, and that primes share hours unevenly; the step proves the prime count; the factor is in [1] because a product of numbers in [3] is in [3]"],"why":"The ratios at 10³, 10⁶, 10⁹ are 1.161, 1.084, 1.054."},
 {"u":"43g5.1","q":"Why does the endless-primes technique of 4j16 alone not give that Σ 1/p passes every bound? Why does π(x) ≈ x/ln x not mean that their difference shrinks?","a":"The squares are endless too, and their sum settles; the technique needed the product; and it is the ratio that settles on 1: the gap grows without bound, and at 10⁹ it is over 2.5 million","w":["Because the primes may not be endless; and the difference does shrink to 0","Because 1/p is not a number; and the difference is always exactly 1","Because 4j16 gives only odd primes; and the ratio does not settle either"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43h"]=window.LADDER_CARDS["43h"]||[]).push(
 {"u":"43h1.1","q":"What does the square-and-multiply technique say? Which powers of 3 are multiplied to give 3²¹⁸, and why those?","a":"To find aᵏ on the clock of n, square a again and again to get a, a², a⁴, a⁸, …, each on the clock, and multiply together those whose places in k written in twos hold a 1; 218 = 2 + 8 + 16 + 64 + 128, written 11011010, so the powers 3², 3⁸, 3¹⁶, 3⁶⁴ and 3¹²⁸ are multiplied, since powers add their counts","w":["Multiply a by itself k − 1 times; all eight powers 3¹ to 3¹²⁸ are multiplied, since 218 < 256","Square a once and multiply k/2 times; the powers 3¹, 3⁴ and 3³² are multiplied, the places of 218 that hold a 0","Square a again and again and keep the last square; only 3¹²⁸ is used, since 128 is the largest power of 2 below 218"],"why":"3²¹⁸ ≡ 489 (mod 1000), by seven squarings and four products."},
 {"u":"43h2.1","q":"What does the power-cost technique say, and where do the squarings and the products come from? About how many products does an exponent of 300 digits need, and how many on the plain road?","a":"Square-and-multiply finds aᵏ on a clock with at most 2⌊log₂ k⌋ products of hours: k in twos has ⌊log₂ k⌋ + 1 places, with one squaring for each place after the first and at most one product for each place after the first that holds a 1; for k < 10³⁰⁰, log₂ k < 997, so at most about 1994 products, against k − 1, about 10³⁰⁰, one product at a time","w":["It needs at most k products; the squarings come from the digits in tens; a 300-digit exponent needs about 300 products, and 600 on the plain road","It needs exactly log₂ k products and no squarings; about 997 products, and 1994 on the plain road","It needs at most 2k products; one squaring for each 1 in k; about 10³⁰⁰ products either way"],"why":"A growth family of log k against one of k."},
 {"u":"43h3.1","q":"What does the halving-remainders technique say? In which case of its proof is the quotient 1, and why does the remainder still fall below half?","a":"In the gcd algorithm each remainder is less than half of the one two rounds before, so on a and b with b ≤ a it ends within about 2 log₂ b rounds; when rᵢ > rᵢ₋₁/2, rᵢ fits only once, so q = 1 and rᵢ₊₁ = rᵢ₋₁ − rᵢ < rᵢ₋₁/2","w":["Each remainder is half the one before, so it ends in log₂ b rounds; the quotient is 1 when rᵢ ≤ rᵢ₋₁/2, and the remainder is then 0","Each remainder is 1 less than the one before, so it takes about b rounds; the quotient is 1 in every round","Each remainder is less than half of the one two rounds before; the quotient is 1 when rᵢ = rᵢ₋₁, and the remainder falls because it is negative"],"why":"For 1071 and 462 it took three rounds; the bound is about 18."},
 {"u":"43h4.1","q":"How is 3²¹⁸ found on the clocks of 8 and 125, and why may the exponent be cut there? How are the two readings put back together into 489?","a":"By the exponent-clock technique the exponent is cut on the clock of each count of units, 3 being a unit of both: c(8) = 4 and 218 ≡ 2, so 3²¹⁸ ≡ 9 ≡ 1 (mod 8); c(125) = 100 and 218 ≡ 18, so 3²¹⁸ ≡ 3¹⁸ ≡ 114 (mod 125); then x = 114 + 125t ≡ 1 (mod 8) gives 2 + 5t ≡ 1, t ≡ 3, and x = 114 + 375 = 489","w":["The exponent is cut on the clocks of 8 and 125 themselves, to 2 and 93; the readings are added: 1 + 114 = 115","The exponent cannot be cut; 3²¹⁸ is computed whole and divided by 8 and by 125; the readings are multiplied","c(8) = 8 and c(125) = 125; the readings 1 and 114 are put back by taking the larger"],"why":"The same last three digits as square-and-multiply gave."},
 {"u":"43h5.1","q":"Why may 402 not be cut to 2 in 2⁴⁰² on the clock of 1000? Why reduce on the clock after every product, and not once at the end?","a":"2 is no unit of the clock of 1000, so the exponent-clock technique does not apply: 2⁴⁰² ≡ 504, not 4; and 3¹²⁸ has 62 digits: reducing after every product keeps every number below n²","w":["It may be cut, since c(1000) = 400; and reducing at the end gives a different answer","Because 402 is even; and reducing after every product is slower and only a habit","Because 1000 is not prime, so no exponent may ever be cut there; and reducing early changes the remainder"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43i"]=window.LADDER_CARDS["43i"]||[]).push(
 {"u":"43i1.1","q":"What does the two-key technique say, and how are n, e and d chosen? Which line spends the little technique, and why is the case p ∣ m split off?","a":"n = pq for different primes, c = (p − 1)(q − 1), e has gcd(e, c) = 1 and d is its undo on the clock of c, so ed = 1 + tc; then (m^e)^d ≡ m (mod n) for every integer m; when p ∤ m, m^(ed) = m · (m^(p − 1))^(t(q − 1)) ≡ m (mod p) by the little technique, which needs p ∤ m; when p ∣ m both sides are multiples of p, so the technique holds for every m","w":["n is prime, e is any power and d = e − 1; (m^e)^d ≡ 1; the little technique is spent on the last line; p ∣ m is split off because then the lock fails","n = pq, e and d are undoes on the clock of n; (m^e)^d ≡ m only for units m; the little technique is not used; the case p ∣ m cannot happen","n = p + q, with ed = c; (m^e)^d ≡ m^c; the little technique gives m^n ≡ m; p ∣ m is split off because m must be prime"],"why":"The printed key is (n, e); the home key is d."},
 {"u":"43i2.1","q":"How is the home key 2753 found from e = 17 and c = 3120? Why does locking with e = 17 take only five products?","a":"The gcd algorithm on 3120 and 17 ends at 1, and reading it back gives 1 = 2 · 3120 − 367 · 17, so d ≡ −367 ≡ 2753 (mod 3120); and 17 is 10001 in twos, so square-and-multiply takes four squarings and one more product","w":["d = 3120 − 17 · 21 = 2753 by division; locking takes five products because 17 has two digits","d is found by trying every power up to 2753; locking takes five products because 17 = 5 + 12","d = 3233 − 480 by taking away; locking takes five products because 61 and 53 are primes"],"why":"Unlocking with 2753 takes fifteen."},
 {"u":"43i3.1","q":"What does the count-gives-factors technique say? Why does it make finding c from n as hard as factoring n?","a":"If n = pq for different primes and c = (p − 1)(q − 1), then p and q are the two roots of x² − (n − c + 1)x + n = 0, since p + q = n − c + 1 and pq = n; so whoever has c and n has p and q by the quadratic formula, and a fast road to c would be a fast road to the factors","w":["p and q are the roots of x² − cx + n = 0; finding c is easy, since c = n − 1","c = p + q; finding c is hard because c is larger than n","p and q are the roots of x² − nx + c = 0; finding c is as hard as factoring because c is prime"],"why":"For 3233 and 3120: x = 57 ± 4 = 61, 53."},
 {"u":"43i4.1","q":"What does the turned-key technique say? Why does the check s^e ≡ m pass for a true signature, and why can a forger not make one?","a":"A signature on m is s = m^d on the clock of n, and anyone holding (n, e) accepts it exactly when s^e ≡ m; the check passes since (m^d)^e = m^(ed) ≡ m by the two-key technique with the keys turned; a forger would need m^d and d is unknown: making an s that passes is unlocking a lock that was never locked","w":["A signature is s = m^e, checked with d; it passes because e is printed; a forger cannot make one because m is secret","A signature is s = m · d; the check passes because d divides s; a forger cannot make one because n is prime","A signature is s = m^d, and the check is s^d ≡ m; it passes by the little technique; a forger can make one from (n, e) alone"],"why":"For m = 123: s = 2746, and 2746¹⁷ ≡ 123 (mod 3233)."},
 {"u":"43i5.1","q":"Why must d be the undo of e on the clock of c, not of n? Why does a small message locked with e = 3 give itself away?","a":"Exponents cancel on the clock of c, the count of units; on the clock of n the powers would not cancel; and if m³ < n the lock never went round the clock, so an ordinary cube root unlocks it","w":["d may be the undo on either clock; and a small message is safe, since 3 is prime","Because n is larger than c; and a small message gives itself away because 3 divides n","Because c is prime; and m³ is always larger than n"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43j"]=window.LADDER_CARDS["43j"]||[]).push(
 {"u":"43j1.1","q":"What does the root-bound technique say, and why is the smaller factor at most √n? Why is it too slow for a number of three hundred digits?","a":"A number n above 1 that is not prime has a prime factor at most √n: if n = jk with 1 < j ≤ k, then j² ≤ jk = n, and a prime divisor of j is at most j; for n ≈ 10³⁰⁰ that is the primes up to 10¹⁵⁰, about 3 × 10¹⁴⁷ divisions: the steps grow like a power of n itself, not of its number of digits","w":["Every factor of n is at most √n, since j · k = n; it is too slow because primes are hard to list","A number that is not prime has a prime factor at most n/2; for 300 digits that is 150 divisions, which is slow","A prime n has a factor at most √n; it is too slow because √n has no decimal"],"why":"For 97: 2, 3, 5, 7 all fail, so 97 is prime."},
 {"u":"43j2.1","q":"What is a witness, and what does it prove? What does the every-base-liar technique say, and why does 561 meet its condition?","a":"An a with gcd(a, n) = 1 and a^(n − 1) ≢ 1 (mod n); it proves n composite without finding a factor; if n has no repeated prime factor and p − 1 divides n − 1 for every prime p dividing n, then a^(n − 1) ≡ 1 (mod n) for every a with gcd(a, n) = 1; 561 = 3 · 11 · 17, and 2, 10 and 16 all divide 560","w":["A witness is a factor of n; it proves n prime; every composite n has a^(n − 1) ≡ 1 for every a; 561 meets it because 561 is odd","A witness is an a with a^(n − 1) ≡ 1; it proves n prime; the technique says no composite passes the little test; 561 = 3 · 187","A witness is an a sharing a factor with n; it finds a factor; the technique needs n to be a prime power; 561 = 3 · 11 · 17 has three of them"],"why":"So the little test cannot prove 561 composite with any base that shares nothing with it."},
 {"u":"43j3.1","q":"What does the strong-test technique say, and why must the chain pass −1 on a prime clock? How does the chain for 561 with base 2 prove 561 composite, and how does it hand over a factor?","a":"If n is an odd prime, n − 1 = 2ˢd with d odd, and n ∤ a, then either a^d ≡ 1, or a^(2ʳd) ≡ −1 for some r below s; on a prime clock the only square roots of [1] are ±[1], so the last hour before [1] in the chain must be −[1]; with 560 = 2⁴ · 35 the chain is 263, 166, 67, 1, and 67 is a square root of 1 that is neither 1 nor −1, so 561 is composite; 561 ∣ (67 − 1)(67 + 1) and gcd(66, 561) = 33 gives 561 = 33 · 17","w":["If n is prime then a^d ≡ −1 always; the chain passes −1 because n is odd; for 561 the chain never reaches 1, and the factor is 2","If n is prime the chain is 1 at every place; the chain for 561 is 263, 166, 67, 1 and shows 561 prime; no factor comes","If n is odd then a^(n − 1) ≡ 1; the chain passes −1 on every clock; for 561 the chain ends at 67, and 67 is the factor"],"why":"A strong witness: at most a quarter of the bases are not, held in trust."},
 {"u":"43j4.1","q":"What does the binomial-test technique say? Why does q to the power j not divide (n choose q) when n is not prime?","a":"If gcd(a, n) = 1 and n ≥ 2, then n is prime exactly when (x + a)ⁿ and xⁿ + a have the same coefficients on the clock of n; with q a prime factor of n and qʲ its highest power dividing n, the top n(n − 1)⋯(n − q + 1) has q to the power j only, from n, and the bottom q! takes one q away","w":["n is prime exactly when (x + a)ⁿ = xⁿ on every clock; qʲ does not divide (n choose q) because q! is larger than n","n is prime exactly when a^n ≡ a; qʲ does not divide it because (n choose q) is odd","n is prime exactly when (x + a)ⁿ has n + 1 coefficients; qʲ does not divide (n choose q) because q does not divide n"],"why":"With n = 15 and q = 3: (15 choose 3) = 455, which 3 does not divide."},
 {"u":"43j5.1","q":"Why does passing 50 rounds of the strong test not make n prime for certain? When does a strong witness hand over a factor, and when does it not?","a":"It gives prime with an exception rate below 4⁻⁵⁰, which is not certainty; and a factor comes only when an odd square root of 1 appears, as 67 did: a power that never reaches 1 gives none","w":["50 rounds are a proof; and every strong witness hands over a factor","Because 50 is even; and a witness hands over a factor only when n is prime","Because the test can call a prime composite; and a factor comes when the power never reaches 1"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43k"]=window.LADDER_CARDS["43k"]||[]).push(
 {"u":"43k1.1","q":"What are the staircase [a₀; a₁, …, a_k] and its convergents? What does the neighbour technique say, and why is every convergent in lowest terms?","a":"[a₀; a₁, …, a_k] names a₀ + 1/(a₁ + 1/(⋯ + 1/a_k)), and cut after a_j it gives the convergent p_j/q_j; the convergents obey p_j = a_j p_(j−1) + p_(j−2) and q_j = a_j q_(j−1) + q_(j−2), and neighbours cross-multiply to differ by one: p_j q_(j−1) − p_(j−1) q_j = (−1)^(j−1); so any common divisor of p_j and q_j divides ±1","w":["The staircase is a₀ + 1/a₁ + ⋯ + 1/a_k and its convergents are the partial sums; neighbours differ by 1; each is in lowest terms because the steps are primes","The staircase is a₀ · a₁ ⋯ a_k; the convergents are a_j/a_(j+1); neighbours have equal bottoms; lowest terms comes from the gcd algorithm run again","The staircase names a decimal; the convergents are its digits cut off; neighbours cross-multiply to 0; lowest terms is not always so"],"why":"1071/462 = [2; 3, 7], with convergents 2, 7/3 and 51/22."},
 {"u":"43k2.1","q":"How are the steps of an endless staircase found, and why does it never end for a number that is no fraction? Why does π’s convergent 355/113 come so close?","a":"Take a₀ = ⌊x⌋; if x is not a₀, take x₁ = 1/(x − a₀), which is above 1, and go on with x₁; a stop would write x as a fraction; in π = [3; 7, 15, 1, 292, …] the large step 292 comes next, and it makes the convergent before it very good: 355/113 − π ≈ 2.7 × 10⁻⁷","w":["The steps are the decimal digits of x; it never ends because decimals never end; 355/113 is close because 113 is prime","Take a₀ = ⌊x⌋ and then x₁ = x − a₀; it ends for every number; 355/113 is close because it equals π","The steps are found by the gcd algorithm on x and 1, which always stops; 355/113 is close because the step before it is 1"],"why":"√2 = [1; 2, 2, 2, …] and the golden number is [1; 1, 1, 1, …]."},
 {"u":"43k3.1","q":"What does the convergent-bound technique say? Which line spends the neighbour technique, and why do the convergents alternate sides?","a":"If x is no fraction, its convergents alternate below and above x, and |x − p_j/q_j| < 1/(q_j q_(j+1)) ≤ 1/q_j²; putting x − p_j/q_j over a common bottom leaves the top p_(j−1)q_j − p_j q_(j−1) = (−1)ʲ by the neighbour technique; the bottom is positive, so the sign of the difference is (−1)ʲ, which alternates","w":["The convergents all lie below x, within 1/q_j; the neighbour technique is spent on the last line; they do not alternate","|x − p_j/q_j| < 1/q_j for every fraction; the neighbour technique gives q_(j+1) ≥ q_j; the sides alternate because the steps a_j alternate","The convergents alternate, and |x − p_j/q_j| > 1/q_j²; the neighbour technique is not used; the sides alternate because x is no fraction"],"why":"No fraction with a bottom below 16 604 comes nearer π than 355/113, held in trust."},
 {"u":"43k4.1","q":"Why do the convergents of log₂ 3 say which equal tunings fit a fifth well? How far is 19 steps of the twelve-step tuning from the twelfth 3 : 1?","a":"In equal steps, k fifths come near j octaves when k log₂(3/2) is near j, so when log₂ 3 is near (j + k)/k, and the convergents are the fractions that come nearest for their bottoms; 12 log₂ 3 ≈ 19.020, so 19 steps are 0.02 of a step flat","w":["Because log₂ 3 is a fraction with bottom 12; 19 steps are exactly the twelfth","Because the convergents are the notes of the scale; 19 steps are half a step sharp","Because fifths stack to octaves after 12; 19 steps miss the twelfth by 3 thousandths of a step"],"why":"The bottoms 5, 12, 41, 53 are the equal tunings that fit the fifth best for their size."},
 {"u":"43k5.1","q":"What does the unit-climb technique say, and why does a product of two answers give an answer? How does the staircase of √61 lead to its least answer?","a":"If x₁² − ny₁² = 1 with x₁, y₁ > 0, the pairs given by x_k + y_k√n = (x₁ + y₁√n)ᵏ all have x_k² − ny_k² = 1; (x + y√n)(x − y√n) = x² − ny², and a product of two such numbers is one of the same kind, with the sizes multiplying; √61 has a block of 11 steps, an odd block, so the convergent before its end gives 29718² − 61 · 3805² = −1, and squaring turns −1 into 1: 1 766 319 049 and 226 153 980","w":["Every pair (kx₁, ky₁) is an answer; products are answers because sizes add; √61 gives its least answer at the first convergent","If x₁² − ny₁² = 1 then no other answer exists; √61 has no block, so its answer is found by trying y = 1, 2, 3, …","The pairs from (x₁ + y₁√n)ᵏ have x² − ny² = k; √61 has a block of 4 steps, which gives 8² − 61 · 1² = 3"],"why":"A search by trying y would need over two hundred million tries."},
 {"u":"43k6.1","q":"Why is [1; 2, 2] not 1 + ½ + ½? Why does failing for y up to 1000 not show x² − 61y² = 1 has no answer?","a":"The steps nest: 1 + 1/(2 + 1/2) = 7/5; and the least answer has y = 226 153 980: a search is not a proof","w":["It is 1 + ½ + ½ = 2; and failing up to 1000 does show there is no answer","Because the steps multiply, giving 4; and 61 is prime, so no answer exists","Because [1; 2, 2] = 1.22; and the answers are all below 1000"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43l"]=window.LADDER_CARDS["43l"]||[]).push(
 {"u":"43l1.1","q":"What is the clock log of a to the base g, and why is there exactly one from 0 to p − 2? What does the clock-log technique say, and why is the sum taken on the clock of p − 1?","a":"For a full hand [g] of the clock of a prime p, it is the k from 0 to p − 2 with [a] = [g]ᵏ; there is exactly one since the powers of a full hand are every unit, each once in p − 1 powers; log_g(ab) ≡ log_g a + log_g b and log_g(aᵐ) ≡ m log_g a, both mod p − 1, since [g]^(j + k) = [g]ʲ[g]ᵏ and exponents live on the clock of p − 1 by the exponent-clock technique","w":["It is the power k with gᵏ = a on the line; there is one because logs are one-to-one; logs add on the clock of p","It is the undo of a on the clock of g; there may be many; log_g(ab) = log_g a · log_g b on the clock of p − 1","It is any k with [g]ᵏ = [a]; there is exactly one from 0 to p; logs add on the clock of p + 1, the count of hours"],"why":"On the clock of 13: log₂ 3 = 4, log₂ 5 = 9, and 13 ≡ 1 (mod 12) = log₂ 15."},
 {"u":"43l2.1","q":"What does the shared-secret technique say, and why do both sides reach the same hour? What does a listener see, and which clock log would let her follow?","a":"With A = gᵃ and B = gᵇ on the clock of p, Bᵃ ≡ Aᵇ (mod p), so both reach the hour g^(ab) without either sending it, by power-of-a-power carried to the clock; a listener sees p, g, A and B, here 23, 5, 8 and 19, and the clock log log₅ 8 = 6 would give the first private power","w":["A · B ≡ g^(a + b), which both can compute; a listener sees only p; the log of 23 would let her follow","Bᵃ ≡ Aᵇ only when a = b; a listener sees a and b; no log is needed","Aᵃ ≡ Bᵇ, so each raises its own number; a listener sees the shared hour 2; log₂ 5 would let her follow"],"why":"19⁶ ≡ 2 and 8¹⁵ ≡ 2 (mod 23)."},
 {"u":"43l3.1","q":"What does the step-and-stride technique say, and why is every k some mi + j? How is log₅ 8 found on the clock of 23?","a":"With m the least whole number having m² ≥ p − 1, list g⁰, …, g^(m − 1), then compute a, a·g^(−m), a·g^(−2m), …; the first found in the list, a·g^(−mi) = gʲ, gives log_g a = mi + j, after at most about 2m products; every k from 0 to p − 2 is mi + j with i and j below m, by division with remainder; for 23, m = 5, the list is 1, 5, 2, 10, 4, and 5⁵ ≡ 20 with undo 15; 8 is not in the list, 8 · 15 = 120 ≡ 5 = 5¹ is, so log₅ 8 = 5 + 1 = 6","w":["Try k = 0, 1, 2, … in turn; every k is mi + j because m is prime; log₅ 8 is found after 8 products as 8","List every power of g and read the log off; k = mi + j because m = p − 1; log₅ 8 = 3 since 5³ = 125 ≡ 8","List g⁰ to g^(m − 1) with m = p/2; every k is m + j; log₅ 8 is found by dividing 8 by 5 on the clock"],"why":"About 2√p products, against p."},
 {"u":"43l4.1","q":"What does the split-log technique say? How is log₂ 10 on the clock of 37 split onto the clocks of 4 and 9?","a":"If p − 1 = uv with u and v sharing nothing, then log_g a on the clock of u is the log of a^v to the base g^v, which has order u, and likewise for v, and the two readings are put back by the remainder technique; 36 = 4 · 9: 2⁹ ≡ 31 has order 4 and 10⁹ ≡ 1, so x ≡ 0 (mod 4); 2⁴ = 16 has order 9 and 10⁴ ≡ 10 = 16⁶, so x ≡ 6 (mod 9); together log₂ 10 = 24","w":["A log splits as the sum of the logs on any two clocks; 36 = 6 · 6, and both readings are 4, so the log is 8","If p = uv the log splits onto the clocks of u and v; 37 is prime, so log₂ 10 cannot be split","log_g a on the clock of u is the log of a^u; the readings are x ≡ 6 (mod 4) and x ≡ 0 (mod 9), giving 18"],"why":"So a clock for secrets needs p − 1 with a large prime factor."},
 {"u":"43l5.1","q":"Why is g^(a + b) not the shared secret? Why does the exchange alone not stop a listener who can change the messages?","a":"Anyone can multiply A and B; the secret is g^(ab), which needs a or b; and a listener who changes messages stands in the middle and agrees one secret with each side: each side must sign what it sends","w":["g^(a + b) is the secret; and the exchange stops every listener","Because a + b is larger than p; and a listener cannot change messages on a prime clock","Because g^(a + b) cannot be computed; and signing is of no help"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43·cb7"]=window.LADDER_CARDS["43·cb7"]||[]).push(
 {"u":"43·cb7.1.1","q":"What does the clock-chain technique say? Why is 3 a unit of every clock in the chain from 10ᵏ?","a":"Starting from 10ᵏ and taking the count of units again and again, the clocks are all powers of 2 times powers of 5, 3 is a unit of each, and the chain reaches the clock of 1 in exactly 3k steps: k steps take away one 5 at a time, reaching 2^(2k), and 2k more halve down to 1; no clock in the chain has 3 as a factor, so 3 shares nothing with any of them","w":["The chain from 10ᵏ reaches the clock of 1 in k steps; 3 is a unit because 3 is prime","The clocks in the chain are powers of 3; 3 is a unit of each because 3 divides each","The chain never reaches the clock of 1; 3 is a unit only of the first clock, 10ᵏ"],"why":"From 10¹⁰ the chain has thirty clocks."},
 {"u":"43·cb7.2.1","q":"What does the tower-freeze technique say? Why does the value on the clock of 1 fix every value above it in the chain?","a":"For every k, the last k digits of 3↑↑b are the same for every b ≥ 3k + 1; 3↑↑b on the clock mᵢ depends only on 3↑↑(b − 1) on the clock mᵢ₊₁, by the exponent-clock technique, since 3 is a unit of mᵢ; on the clock of 1 every value is 0, one hour, so each value is fixed by the one below, down the chain 3k times","w":["The last k digits of 3↑↑b are the same for every b ≥ k; the clock of 1 fixes the rest because 3¹ = 3","The first k digits of 3↑↑b freeze; the clock of 1 has one hour, so every tower is 1","The last k digits freeze only for b above 10ᵏ; the value on the clock of 1 is 3, which is carried up the chain"],"why":"The truth is lower: 7 from b = 2, 87 from b = 3, 387 from b = 4."},
 {"u":"43·cb7.3.1","q":"Why may the chain use orders in place of counts of units? How do the last two digits 87 come from the clocks of 4 and 20?","a":"A power comes back after its order, and the order divides the count, so the exponent may be read on the clock of the order, which is smaller; a tower is odd, so 3 to it is 3 on the clock of 4, where [3] has order 2; [3] has order 4 on the clock of 20, so the next level is 3³ = 27 ≡ 7; and order 20 on the clock of 100 gives 3⁷ = 2187 ≡ 87","w":["Orders are larger than counts, so they are safer; 87 comes from 3⁴ = 81 and 3² = 9 added to 90","Orders and counts are always equal; 87 comes from 3²⁰ on the clock of 100","Orders may be used because 3 is prime; on the clock of 4 the tower is 1, on 20 it is 3, and 3³ = 27 ≡ 87"],"why":"Then 3⁸⁷ ≡ 387 (mod 1000)."},
 {"u":"43·cb7.4.1","q":"Why are the last ten digits of 3↑↑↑3 the same as those of a tower of 31 threes? Why do clocks give the last digits of 3↑↑↑3 and not its first digit?","a":"3↑↑↑3 = 3↑↑(3↑↑3) is a tower of 7 625 597 484 987 threes, far above 3 · 10 + 1 = 31, and by the tower-freeze technique the last ten digits are the same for every height from 31 on; clocks see remainders, and the first digit depends on the whole size of the number, which no chain of clocks sees","w":["Because 3↑↑↑3 is a tower of exactly 31 threes; clocks give the first digit too, on the clock of 10","Because every tower of threes ends in the same ten digits from height 2; the first digit is 3, the base","Because 31 is prime; clocks cannot give the first digit because it is 0"],"why":"3↑↑↑3 ends in 2464195387."},
 {"u":"43·cb7.5.1","q":"Why does the last-three-digit hour of 3↑↑b not need 3↑↑(b − 1) on the clock of 1000? Why does the chain need the base to be a unit of every clock?","a":"The exponent goes on the clock of the order of 3, which is 100, not of 1000; and the exponent-clock technique holds for units only: for the base 2 the clock of 10 is split first by the remainder technique","w":["It does need it on the clock of 1000; and the chain works for any base","Because 1000 is not prime; and a base that is no unit has no powers","Because the exponent goes on the clock of 10; and the base must be a unit so that it is odd"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43·cb19"]=window.LADDER_CARDS["43·cb19"]||[]).push(
 {"u":"43·cb19.1.1","q":"What is nℤ, and why is the copy a + 12ℤ the hour [a]? Why does adding the copies of 12ℤ give the clock’s adding?","a":"nℤ is the multiples of n, a part-group of the integers under adding; b is in a + 12ℤ exactly when b − a is in 12ℤ, which is when b ≡ a (mod 12), so the copy is the hour; adding the sets member by member gives (a + 12ℤ) + (b + 12ℤ) = (a + b) + 12ℤ, which is [a] + [b] = [a + b]","w":["nℤ is the numbers below n; the copy a + 12ℤ is [a] because both have 12 members; copies add because the clock is small","nℤ is the units of the clock of n; a + 12ℤ is the hour [12a]; adding copies gives the clock’s multiplying","nℤ is the multiples of n; a + 12ℤ is the hour [a] only for a below 12; adding copies fails because the integers are endless"],"why":"So ℤ/n is ℤ’s copies of nℤ, n of them."},
 {"u":"43·cb19.2.1","q":"What does the copies-combine technique say, and what is a normal part-group? Why can the copies of {e, s₁₂} in S₃ not be multiplied?","a":"The function (aH)(bH) = abH is well defined exactly when gH = Hg for every g in G, and then the copies form a group with eH = H doing nothing; such an H is normal in G, the same from either side, and G/H names the group of its copies; in S₃, s₁₃{e, s₁₂} ≠ {e, s₁₂}s₁₃, so the swap’s part-group is not normal and the technique gives different answers from different members","w":["The function is well defined for every part-group; a normal part-group is one with a prime count; the copies of {e, s₁₂} overlap","The function is well defined exactly when gh = hg for all members; normal means turn-about; {e, s₁₂} has too few members","The function is well defined when H is all of G only; a normal part-group is the turns; S₃ has no copies of {e, s₁₂}"],"why":"The three turns {e, r, r²} are normal, with two copies."},
 {"u":"43·cb19.3.1","q":"What does the sent-to-e technique say? Why are the even shuffles normal in Sₙ?","a":"For a product-keeping map f, the set K of members sent to e′ is a normal part-group, and f(a) = f(b) exactly when aK = bK; the sign of a shuffle, +1 for even and −1 for odd, keeps products and sends exactly the even shuffles to +1, so they are such a K","w":["K is a part-group and never normal; the even shuffles are normal because there are more of them","f(a) = f(b) exactly when a = b; the even shuffles are normal because each is its own undo","K is all of G; the even shuffles are normal because the sign sends them to −1"],"why":"Normal without a single copy checked by hand."},
 {"u":"43·cb19.4.1","q":"What does the image-matching technique say, and which technique makes the map well defined and one-to-one? How does it show that the units of a prime clock under times match a clock under adding?","a":"If f is a product-keeping map from G with K the set sent to e′, then aK ↦ f(a) is a matching of G/K with the image of f that keeps products; it is well defined and one-to-one by the sent-to-e technique, both ways of its last line; the clock log [g]ᵏ ↦ [k] turns times into plus, is onto the clock of p − 1, and sends nothing but [1] to [0], so the units match that clock","w":["G matches its image under any map; the copies-combine technique makes it well defined; the units match the clock of p because there are p of them","G/K matches G; the part-and-normal technique makes it one-to-one; the units match a clock under adding because [a] + [b] = [ab]","The image of f matches K; no technique is needed; the units of a prime clock match the clock of 2 under the sign"],"why":"ℤ/nℤ matches the clock of n: 43a’s clock, named as a quotient."},
 {"u":"43·cb19.5.1","q":"What does the part-and-normal technique say? Where does the proof use that N is normal, and what goes wrong in S₃ without it?","a":"If H is a part-group of G and N is normal in G, then HN is a part-group, H ∩ N is normal in H, and HN/N matches H/(H ∩ N), by h(H ∩ N) ↦ hN; normal N gives hnh⁻¹ in N, so HN = NH and products of members of HN stay in HN; in S₃, {e, s₁₂}{e, s₁₃} has four members, and 4 does not divide 6, so it is no part-group","w":["HN is a part-group for any two part-groups; normal is not used; in S₃ the product has six members","If N is normal then H ∩ N = {e}; normal is used to make H turn-about; in S₃ the product is empty","HN/N matches H for every H and N; normal is used once, at the last line; in S₃ the product has two members"],"why":"With 4ℤ and 6ℤ: 2ℤ/6ℤ matches 4ℤ/12ℤ, three copies each."},
 {"u":"43·cb19.6.1","q":"What does the quotient-parts technique say? Why does the clock of 12 have exactly six part-groups?","a":"If N is normal in G, then M ↦ M/N matches the part-groups M of G that hold N with the part-groups of G/N; M/N is normal in G/N exactly when M is normal in G; and then (G/N)/(M/N) matches G/M; the part-groups of ℤ holding 12ℤ are dℤ for d dividing 12, one for each of 1, 2, 3, 4, 6 and 12","w":["Every part-group of G gives one of G/N; the clock of 12 has twelve part-groups, one for each hour","The part-groups of G/N match those of N; the clock of 12 has six because 12/2 = 6","G/N has no part-groups but itself; the clock of 12 has six because it has four units and two others"],"why":"A quotient of a quotient is a quotient."},
 {"u":"43·cb19.7.1","q":"Why does gH = Hg not give gh = hg for each h? Why does K = {e} make a map one-to-one and not onto?","a":"The sets agree, not the members: r{e, r, r²} = {e, r, r²}r while s₁₂ does not turn about with r; and K = {e} says different members go to different places, while onto is another matter: ℤ → ℤ, k ↦ 2k","w":["It does give gh = hg; and K = {e} makes a map onto","Because H is never normal; and K = {e} means the map sends everything to e","Because g is not in H; and a one-to-one map is always onto"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["43·cb37"]=window.LADDER_CARDS["43·cb37"]||[]).push(
 {"u":"43·cb37.1.1","q":"What does the pitch-clock technique say, and which technique of 43a makes a note one hour? Which note is a fourth, 5 steps, above G?","a":"In twelve equal steps, the notes are the hours of the clock of 12, and moving a tune up by an interval of k steps adds [k] to every note; by the difference-test technique counts differing by a multiple of 12 are one hour, which is one note; G = [10], and [10] + [5] = [15] = [3] = C","w":["The notes are the hours of the clock of 7; the clock-cancel technique makes a note one hour; a fourth above G is D","The notes are the hours of the clock of 12, and moving a tune up multiplies every hour by k; the carry technique; a fourth above G is B","The notes are the frequencies 440 · k; the difference test; a fourth above G is [15], a new note outside the clock"],"why":"A fifth above E: [7] + [7] = [14] = [2] = B."},
 {"u":"43·cb37.2.1","q":"What does the interval-cycle technique say, and which technique of 43b gives the step that reaches every multiple of d? How many notes does a stack of fourths reach, and how many a stack of major thirds?","a":"Stacking an interval of k steps on the clock of n reaches exactly the hours that are multiples of d = gcd(k, n), n/d of them, and comes back home after n/d stacks; by the gcd-as-a-sum technique d = kx + ny, so x stacks reach [d]; fourths, k = 5, share nothing with 12 and reach all 12 notes; major thirds, k = 4, reach 3","w":["Stacking k steps always reaches every hour; the prime-clock-field technique; fourths reach 5 notes and major thirds 4","Stacking k steps reaches k hours; the clock-cancel technique; fourths reach 7 notes and major thirds 6","Stacking reaches the multiples of gcd(k, n); the gcd-as-a-sum technique; fourths reach 6 notes and major thirds 12"],"why":"The intervals that walk through every note are the units of the clock of 12."},
 {"u":"43·cb37.3.1","q":"What does the tone-and-semitone technique say, and why is gcd(3t + s, 5t + 2s) the same as gcd(t, s)? Counted in whole tones, why has the fifth no hour?","a":"If the seven-note scale has five tones of t equal steps and two semitones of s steps, its octave is a clock of 5t + 2s and its fifth is 3t + s steps, and the fifths reach every note exactly when t and s share no divisor; any d dividing both divides 2(3t + s) − (5t + 2s) = t and 3(5t + 2s) − 5(3t + s) = s, and any divisor of t and s divides both; in tones the octave is a clock of 6, and the fifth is three and a half tones","w":["The octave is a clock of 7t and the fifth is 4t; the gcds agree because both are 1; the fifth has no hour because it is larger than the octave","The octave is a clock of 5t + 2s and the fifth 2t + s; the gcds agree because t > s; in tones the fifth is the hour [3]","The octave is always the clock of 12; the gcds agree by the remainder technique; in tones the fifth has no hour because 6 is even"],"why":"t = 2, s = 1 is the piano: clock 12, fifth 7."},
 {"u":"43·cb37.4.1","q":"What does the realign technique say, and which technique of 43c proves it? A drummer loops a 5-beat figure over 4-beat bars. After how many bars does it start with the bar again?","a":"A figure of a beats played over bars of b beats starts with a bar again first after lcm(a, b) = ab/gcd(a, b) beats; the shared-divisor technique proves it: the beats x with x ≡ 0 (mod a) and x ≡ 0 (mod b) are the multiples of the lcm; 5 over 4 gives 20 beats, five bars","w":["They start together after a + b beats; the remainder technique; 5 over 4 lines up after 9 beats","They start together after ab beats always; the two-clock technique; 5 over 4 lines up after 20 bars","They never start together again unless a = b; the shared-divisor technique; 5 over 4 never lines up"],"why":"6 over 4 lines up after 12 beats, not 24."},
 {"u":"43·cb37.5.1","q":"Someone says that since a tone is two semitones, a tuning of 24 quarter tones has a circle of fifths through all 24. What does the tone-and-semitone technique say?","a":"With t = 4 and s = 2 the clock is 24 and the fifth is 14 steps; t and s share 2, so gcd(14, 24) = 2 and the fifths reach only 12 of the 24 notes: they never reach the quarter tones","w":["With t = 4 and s = 2 the fifth is 7 steps, which shares nothing with 24, so the fifths reach all 24","It says nothing about 24 steps, since it is for the clock of 12 only","With t = 4 and s = 2 the fifths reach 2 notes, since gcd(14, 24) = 2"],"why":"The fifths reach every note exactly when t and s share no divisor."});
/* end phase F und_r43 */
